INTERRUPTED = [33]


def _get_function(name):
    if name in ("L2A_Dif_ModDes_SatAlfa", "L2A_Dif_ModDes_SatAlfaAlt"):
        mod = __import__(name)
        return getattr(mod, name)
    root = HERE[:HERE.index(os.sep + "papers" + os.sep)]
    path = os.path.join(root, "dissertation", "code", "2016-second-level-adaptation-toolbox",
                        "Toolbox Adaptacao L2", "Old", name + ".py")
    if not os.path.exists(path):
        raise ImportError(f"{name} port not found at {path}")
    sys.path.insert(0, os.path.dirname(path))
    spec = importlib.util.spec_from_file_location(name + "_old", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return getattr(mod, name)


def main(argv=None):
    p = argparse.ArgumentParser(description="MATLAB command history 17/05/2016")
    p.add_argument("--index", type=int, default=len(CALLS) - 1)
    p.add_argument("--all", action="store_true")
    p.add_argument("--list", action="store_true")
    a = p.parse_args(argv)
    if a.list:
        for i, (f, args) in enumerate(CALLS):
            print(i, f, args)
        return
    idx = [i for i in range(len(CALLS)) if i not in INTERRUPTED] if a.all else [a.index]
    for i in idx:
        f, args = CALLS[i]
        print(f">> [{i}] {f}{args}")
        _get_function(f)(*args)
    plt.show()


if __name__ == "__main__":
    main()
